export type RevisionNumber = number;

export type EventCursor = number;

export type ResourceQuote = Readonly<Record<string, number>>;

export interface ProposalReference {
  readonly proposal_id: Identifier;
  readonly revision: RevisionNumber;
}

export interface TrialReference {
  readonly trial_id: Identifier;
  readonly revision: RevisionNumber;
}

export interface SessionReference {
  readonly agent_session_id: Identifier;
  readonly revision: RevisionNumber;
}

export interface ContextReference {
  readonly context_id: Identifier;
  readonly revision: RevisionNumber;
}

export interface MemoryReference {
  readonly memory_id: Identifier;
  readonly revision: RevisionNumber;
}

export interface ReceiptReference {
  readonly evaluation_id: Identifier;
  readonly receipt_revision: RevisionNumber;
}

export interface UsageReference {
  readonly operation_id: Identifier;
  readonly usage_revision: RevisionNumber;
}

export interface ExternalSnapshot {
  readonly kb_version: IdentityObservation;
  readonly harness_version: IdentityObservation;
  readonly memory_revision: MemoryReference;
  readonly memory_epoch: EventCursor;
  readonly evidence_cutoff: EventCursor;
  readonly knowledge?: TrialKnowledgeBinding;
}

export interface OwnerReference {
  readonly ref_id: Identifier;
  readonly owner: "wiki" | "native_control_plane" | "profiler" | "program_store" | "evaluation_worker" | "journal";
  readonly record_id: Text;
  readonly digest: Digest;
  readonly digest_scope: Text;
  readonly locator: Text;
  readonly byte_length?: EventCursor;
}

export interface VersionLockEntry {
  readonly version_lock_digest: Digest;
  readonly lock: VersionLock;
}

export interface SelectionItem {
  readonly source_ref_id: Identifier;
  readonly selection: "included" | "excerpt" | "reference_only" | "omitted";
  readonly reason: Text;
  readonly selected_digest?: Digest;
}

export interface UsageRevision {
  readonly operation_id: Identifier;
  readonly usage_revision: RevisionNumber;
  readonly supersedes_revision?: RevisionNumber;
  readonly basis: "cumulative" | "incremental";
  readonly usage: ResourceQuote;
  readonly receipt_ref_id: Identifier;
}

export interface RewardRevision {
  readonly reward_revision: RevisionNumber;
  readonly supersedes_revision?: RevisionNumber;
  readonly receipt_keys: ReadonlyArray<ReceiptReference>;
  readonly usage_keys: ReadonlyArray<UsageReference>;
  readonly state: "pending" | "ready" | "revoked";
}

export interface ReceiptRevision {
  readonly receipt_revision: RevisionNumber;
  readonly supersedes_revision?: RevisionNumber;
  readonly receipt_digest: Digest;
  readonly receipt_ref_id: Identifier;
  readonly observation?: ScoringObservation;
}

export interface EvaluationPlan {
  readonly plan_id: Identifier;
  readonly task_contract_hash: Digest;
  readonly casepack_digest: Digest;
  readonly purpose: "build" | "correctness" | "benchmark" | "profile" | "quality";
  readonly stage: "screen" | "confirm" | "final";
  readonly level: "smoke" | "quick" | "full";
  readonly attempt: RevisionNumber;
  readonly replicate: RevisionNumber;
  readonly replicate_of_evaluation_id?: Identifier;
  readonly operation_id: Identifier;
  readonly version_lock_digest: Digest;
  readonly environment_version: IdentityObservation;
  readonly shape_ref_id: Identifier;
  readonly seed: EventCursor;
  readonly measurement_protocol_ref_id: Identifier;
  readonly comparison_baseline: Baseline;
  readonly scoring_baseline: Baseline;
}

export interface FactScope {
  readonly task_contract_hash: Digest;
  readonly program_ids: ReadonlyArray<Identifier>;
}

export interface TaskRun {
  readonly kind: "task_run";
  readonly run_id: Identifier;
  readonly host_task_id: Identifier;
  readonly task_id: Identifier;
  readonly task_contract_hash: Digest;
  readonly version_lock_digest: Digest;
  readonly root_program_id: Identifier;
  readonly kb_version: IdentityObservation;
  readonly harness_version: IdentityObservation;
  readonly environment_version: IdentityObservation;
  readonly policy_digest: Digest;
  readonly reservation_id: Identifier;
  readonly seed: EventCursor;
}

export interface ProposalRevision {
  readonly kind: "proposal_revision";
  readonly proposal_id: Identifier;
  readonly revision: RevisionNumber;
  readonly run_id: Identifier;
  readonly conditions: Text;
  readonly operation: Text;
  readonly expected_outcome: Text;
  readonly stop_conditions: ReadonlyArray<Text>;
  readonly parameter_space_ref_id: Identifier;
}

export interface Trial {
  readonly kind: "trial";
  readonly trial_id: Identifier;
  readonly revision: RevisionNumber;
  readonly run_id: Identifier;
  readonly branch_id: Identifier;
  readonly task_contract_hash: Digest;
  readonly version_lock_digest: Digest;
  readonly parent_program_id: Identifier;
  readonly proposal_revision: ProposalReference;
  readonly external_snapshot: ExternalSnapshot;
  readonly policy_digest: Digest;
  readonly model_route: Identifier;
  readonly reservation_id: Identifier;
  readonly working_program_id: Identifier;
  readonly trial_feedback_cursor: EventCursor;
  readonly execution_state: TrialState;
  readonly settlement_state: SettlementState;
  readonly reward_revisions: ReadonlyArray<RewardRevision>;
}

