  readonly owner_kind: "branch" | "agent_session" | "trial" | "replay_job";
  readonly owner_id: Identifier;
  readonly epoch: RevisionNumber;
  readonly deadline: Text;
  readonly heartbeat_sequence: EventCursor;
  readonly allocation_state: "active" | "reclaiming" | "released";
